/**
 * Retrieves all blog articles.
 * @returns {Array} Array of all blog articles.
 */
export const getAllArticles = () => {
  return blogArticles;
};

/**
 * Retrieves a single blog article by its slug.
 * @param {string} slug - The URL-safe slug of the article.
 * @returns {Object|undefined} The matching article object, or undefined if not found.
 */
export const getArticleBySlug = (slug) => {
  return blogArticles.find(article => article.slug === slug);
};

/**
 * Retrieves all articles that contain a specific tag.
 * @param {string} tag - The tag to filter by.
 * @returns {Array} Array of matching blog articles.
 */
export const getArticlesByTag = (tag) => {
  const lowerTag = tag.toLowerCase();
  return blogArticles.filter(article =>
    article.tags.some(t => t.toLowerCase() === lowerTag)
  );
};
